    "CREATE FUNCTION public.refresh_all_product_views() RETURNS TABLE(view_name character varying, duration_seconds double precision, row_count integer, success boolean)\n    LANGUAGE plpgsql\n    AS $$\nDECLARE\n    v_start TIMESTAMP;\n    v_end TIMESTAMP;\n    v_duration FLOAT;\n    v_count INTEGER;\nBEGIN\n    v_start := clock_timestamp();\n    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_product_management;\n    v_end := clock_timestamp();\n    v_duration := EXTRACT(EPOCH FROM (v_end - v_start));\n    SELECT COUNT(*) INTO v_count FROM mv_product_management;\n    RETURN QUERY SELECT 'mv_product_management'::VARCHAR, v_duration, v_count, true;\n    \n    v_start := clock_timestamp();\n    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_product_sales_trend;\n    v_end := clock_timestamp();\n    v_duration := EXTRACT(EPOCH FROM (v_end - v_start));\n    SELECT COUNT(*) INTO v_count FROM mv_product_sales_trend;\n    RETURN QUERY SELECT 'mv_product_sales_trend'::VARCHAR, v_duration, v_count, true;\n    \n    v_start := clock_timestamp();\n    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_top_products;\n    v_end := clock_timestamp();\n    v_duration := EXTRACT(EPOCH FROM (v_end - v_start));\n    SELECT COUNT(*) INTO v_count FROM mv_top_products;\n    RETURN QUERY SELECT 'mv_top_products'::VARCHAR, v_duration, v_count, true;\n    \n    v_start := clock_timestamp();\n    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_shop_product_summary;\n    v_end := clock_timestamp();\n    v_duration := EXTRACT(EPOCH FROM (v_end - v_start));\n    SELECT COUNT(*) INTO v_count FROM mv_shop_product_summary;\n    RETURN QUERY SELECT 'mv_shop_product_summary'::VARCHAR, v_duration, v_count, true;\nEND;\n$$",
    "CREATE FUNCTION public.refresh_inventory_views() RETURNS TABLE(duration_seconds double precision, row_count integer, success boolean)\n    LANGUAGE plpgsql\n    AS $$\nDECLARE\n    start_time TIMESTAMP;\n    end_time TIMESTAMP;\n    duration FLOAT;\n    rows INTEGER;\nBEGIN\n    start_time := clock_timestamp();\n    \n    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_inventory_summary;\n    \n    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_inventory_by_sku;\n    \n    end_time := clock_timestamp();\n    duration := EXTRACT(EPOCH FROM (end_time - start_time));\n    \n    SELECT COUNT(*) INTO rows FROM mv_inventory_summary;\n    \n    RETURN QUERY SELECT duration, rows, true;\nEND;\n$$",
    "COMMENT ON FUNCTION public.refresh_inventory_views() IS '刷新库存相关物化视图（v4.10.2优化）'",
    "CREATE FUNCTION public.refresh_product_management_view() RETURNS TABLE(duration_seconds double precision, row_count integer, success boolean)\n    LANGUAGE plpgsql\n    AS $$\nDECLARE\n    start_time TIMESTAMP;\n    end_time TIMESTAMP;\n    duration FLOAT;\n    rows INTEGER;\nBEGIN\n    start_time := clock_timestamp();\n    \n    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_product_management;\n    \n    end_time := clock_timestamp();\n    duration := EXTRACT(EPOCH FROM (end_time - start_time));\n    \n    SELECT COUNT(*) INTO rows FROM mv_product_management;\n    \n    RETURN QUERY SELECT duration, rows, true;\nEND;\n$$",
