    "CREATE VIEW semantic.shop_identity_resolution_candidates AS\n WITH active_shop_accounts AS (\n         SELECT sa.id AS shop_account_pk,\n            lower((COALESCE(sa.platform, ''::character varying))::text) AS platform_code,\n            NULLIF(TRIM(BOTH FROM COALESCE(sa.shop_account_id, ''::character varying)), ''::text) AS resolved_shop_account_id,\n            NULLIF(TRIM(BOTH FROM COALESCE(sa.platform_shop_id, ''::character varying)), ''::text) AS candidate_platform_shop_id,\n            NULLIF(TRIM(BOTH FROM COALESCE(sa.store_name, ''::character varying)), ''::text) AS candidate_store_label,\n            COALESCE(NULLIF(TRIM(BOTH FROM COALESCE(sa.platform_shop_id, ''::character varying)), ''::text), NULLIF(TRIM(BOTH FROM COALESCE(sa.shop_account_id, ''::character varying)), ''::text), (sa.id)::text) AS resolved_shop_id\n           FROM core.shop_accounts sa\n        ), identity_rows AS (\n         SELECT active_shop_accounts.platform_code,\n            active_shop_accounts.resolved_shop_id,\n            active_shop_accounts.resolved_shop_account_id,\n            'platform_shop_id'::character varying AS resolution_method,\n            1 AS resolution_priority,\n            lower(active_shop_accounts.candidate_platform_shop_id) AS identity_value_normalized,\n            active_shop_accounts.candidate_platform_shop_id AS identity_source_value\n           FROM active_shop_accounts\n          WHERE (active_shop_accounts.candidate_platform_shop_id IS NOT NULL)\n        UNION ALL\n         SELECT active_shop_accounts.platform_code,\n            active_shop_accounts.resolved_shop_id,\n            active_shop_accounts.resolved_shop_account_id,\n            'shop_account_id'::character varying AS resolution_method,\n            2 AS resolution_priority,\n            lower(active_shop_accounts.resolved_shop_account_id) AS identity_value_normalized,\n            active_shop_accounts.resolved_shop_account_id AS identity_source_value\n           FROM active_shop_accounts\n          WHERE (active_shop_accounts.resolved_shop_account_id IS NOT NULL)\n        UNION ALL\n         SELECT asa.platform_code,\n            asa.resolved_shop_id,\n            asa.resolved_shop_account_id,\n            'alias_match'::character varying AS resolution_method,\n            3 AS resolution_priority,\n            lower(TRIM(BOTH FROM saa.alias_normalized)) AS identity_value_normalized,\n            saa.alias_value AS identity_source_value\n           FROM (active_shop_accounts asa\n             JOIN core.shop_account_aliases saa ON (((saa.shop_account_id = asa.shop_account_pk) AND (saa.is_active = true))))\n          WHERE (NULLIF(TRIM(BOTH FROM COALESCE(saa.alias_normalized, ''::character varying)), ''::text) IS NOT NULL)\n        UNION ALL\n         SELECT active_shop_accounts.platform_code,\n            active_shop_accounts.resolved_shop_id,\n            active_shop_accounts.resolved_shop_account_id,\n            'store_name_match'::character varying AS resolution_method,\n            4 AS resolution_priority,\n            regexp_replace(regexp_replace(lower(TRIM(BOTH FROM active_shop_accounts.candidate_store_label)), '^(shopee|tiktok\\s*shop|tiktok|tk|miaoshou|amazon|lazada)\\s*'::text, ''::text, 'i'::text), '[[:space:]_()/-]+'::text, ''::text, 'g'::text) AS identity_value_normalized,\n            active_shop_accounts.candidate_store_label AS identity_source_value\n           FROM active_shop_accounts\n          WHERE (active_shop_accounts.candidate_store_label IS NOT NULL)\n        )\n SELECT identity_rows.platform_code,\n    identity_rows.identity_value_normalized,\n    identity_rows.identity_source_value,\n    identity_rows.resolved_shop_id,\n    identity_rows.resolved_shop_account_id,\n    identity_rows.resolution_method,\n    identity_rows.resolution_priority\n   FROM identity_rows\n  WHERE (NULLIF(TRIM(BOTH FROM COALESCE(identity_rows.identity_value_normalized, ''::text)), ''::text) IS NOT NULL)",
    "CREATE VIEW semantic.fact_analytics_atomic AS\n WITH raw_analytics AS (\n         SELECT fact_shopee_analytics_daily.platform_code,\n            fact_shopee_analytics_daily.shop_id,\n            fact_shopee_analytics_daily.data_domain,\n            fact_shopee_analytics_daily.granularity,\n            fact_shopee_analytics_daily.metric_date,\n            fact_shopee_analytics_daily.period_start_date,\n            fact_shopee_analytics_daily.period_end_date,\n            fact_shopee_analytics_daily.period_start_time,\n            fact_shopee_analytics_daily.period_end_time,\n            fact_shopee_analytics_daily.raw_data,\n            fact_shopee_analytics_daily.header_columns,\n            fact_shopee_analytics_daily.data_hash,\n            fact_shopee_analytics_daily.ingest_timestamp,\n            fact_shopee_analytics_daily.currency_code\n           FROM b_class.fact_shopee_analytics_daily\n        UNION ALL\n         SELECT fact_shopee_analytics_weekly.platform_code,\n            fact_shopee_analytics_weekly.shop_id,\n            fact_shopee_analytics_weekly.data_domain,\n            fact_shopee_analytics_weekly.granularity,\n            fact_shopee_analytics_weekly.metric_date,\n            fact_shopee_analytics_weekly.period_start_date,\n            fact_shopee_analytics_weekly.period_end_date,\n            fact_shopee_analytics_weekly.period_start_time,\n            fact_shopee_analytics_weekly.period_end_time,\n            fact_shopee_analytics_weekly.raw_data,\n            fact_shopee_analytics_weekly.header_columns,\n            fact_shopee_analytics_weekly.data_hash,\n            fact_shopee_analytics_weekly.ingest_timestamp,\n            fact_shopee_analytics_weekly.currency_code\n           FROM b_class.fact_shopee_analytics_weekly\n        UNION ALL\n         SELECT fact_shopee_analytics_monthly.platform_code,\n            fact_shopee_analytics_monthly.shop_id,\n            fact_shopee_analytics_monthly.data_domain,\n            fact_shopee_analytics_monthly.granularity,\n            fact_shopee_analytics_monthly.metric_date,\n            fact_shopee_analytics_monthly.period_start_date,\n            fact_shopee_analytics_monthly.period_end_date,\n            fact_shopee_analytics_monthly.period_start_time,\n            fact_shopee_analytics_monthly.period_end_time,\n            fact_shopee_analytics_monthly.raw_data,\n            fact_shopee_analytics_monthly.header_columns,\n            fact_shopee_analytics_monthly.data_hash,\n            fact_shopee_analytics_monthly.ingest_timestamp,\n            fact_shopee_analytics_monthly.currency_code\n           FROM b_class.fact_shopee_analytics_monthly\n        UNION ALL\n         SELECT fact_tiktok_analytics_daily.platform_code,\n            fact_tiktok_analytics_daily.shop_id,\n            fact_tiktok_analytics_daily.data_domain,\n            fact_tiktok_analytics_daily.granularity,\n            fact_tiktok_analytics_daily.metric_date,\n            fact_tiktok_analytics_daily.period_start_date,\n            fact_tiktok_analytics_daily.period_end_date,\n            fact_tiktok_analytics_daily.period_start_time,\n            fact_tiktok_analytics_daily.period_end_time,\n            fact_tiktok_analytics_daily.raw_data,\n            fact_tiktok_analytics_daily.header_columns,\n            fact_tiktok_analytics_daily.data_hash,\n            fact_tiktok_analytics_daily.ingest_timestamp,\n            fact_tiktok_analytics_daily.currency_code\n           FROM b_class.fact_tiktok_analytics_daily\n        UNION ALL\n         SELECT fact_tiktok_analytics_weekly.platform_code,\n            fact_tiktok_analytics_weekly.shop_id,\n            fact_tiktok_analytics_weekly.data_domain,\n            fact_tiktok_analytics_weekly.granularity,\n            fact_tiktok_analytics_weekly.metric_date,\n            fact_tiktok_analytics_weekly.period_start_date,\n            fact_tiktok_analytics_weekly.period_end_date,\n            fact_tiktok_analytics_weekly.period_start_time,\n            fact_tiktok_analytics_weekly.period_end_time,\n            fact_tiktok_analytics_weekly.raw_data,\n            fact_tiktok_analytics_weekly.header_columns,\n            fact_tiktok_analytics_weekly.data_hash,\n            fact_tiktok_analytics_weekly.ingest_timestamp,\n            fact_tiktok_analytics_weekly.currency_code\n           FROM b_class.fact_tiktok_analytics_weekly\n        UNION ALL\n         SELECT fact_tiktok_analytics_monthly.platform_code,\n            fact_tiktok_analytics_monthly.shop_id,\n            fact_tiktok_analytics_monthly.data_domain,\n            fact_tiktok_analytics_monthly.granularity,\n            fact_tiktok_analytics_monthly.metric_date,\n            fact_tiktok_analytics_monthly.period_start_date,\n            fact_tiktok_analytics_monthly.period_end_date,\n            fact_tiktok_analytics_monthly.period_start_time,\n            fact_tiktok_analytics_monthly.period_end_time,\n            fact_tiktok_analytics_monthly.raw_data,\n            fact_tiktok_analytics_monthly.header_columns,\n            fact_tiktok_analytics_monthly.data_hash,\n            fact_tiktok_analytics_monthly.ingest_timestamp,\n            fact_tiktok_analytics_monthly.currency_code\n           FROM b_class.fact_tiktok_analytics_monthly\n        UNION ALL\n         SELECT fact_miaoshou_analytics_daily.platform_code,\n            fact_miaoshou_analytics_daily.shop_id,\n            fact_miaoshou_analytics_daily.data_domain,\n            fact_miaoshou_analytics_daily.granularity,\n            fact_miaoshou_analytics_daily.metric_date,\n            fact_miaoshou_analytics_daily.period_start_date,\n            fact_miaoshou_analytics_daily.period_end_date,\n            fact_miaoshou_analytics_daily.period_start_time,\n            fact_miaoshou_analytics_daily.period_end_time,\n            fact_miaoshou_analytics_daily.raw_data,\n            fact_miaoshou_analytics_daily.header_columns,\n            fact_miaoshou_analytics_daily.data_hash,\n            fact_miaoshou_analytics_daily.ingest_timestamp,\n            fact_miaoshou_analytics_daily.currency_code\n           FROM b_class.fact_miaoshou_analytics_daily\n        UNION ALL\n         SELECT fact_miaoshou_analytics_weekly.platform_code,\n            fact_miaoshou_analytics_weekly.shop_id,\n            fact_miaoshou_analytics_weekly.data_domain,\n            fact_miaoshou_analytics_weekly.granularity,\n            fact_miaoshou_analytics_weekly.metric_date,\n            fact_miaoshou_analytics_weekly.period_start_date,\n            fact_miaoshou_analytics_weekly.period_end_date,\n            fact_miaoshou_analytics_weekly.period_start_time,\n            fact_miaoshou_analytics_weekly.period_end_time,\n            fact_miaoshou_analytics_weekly.raw_data,\n            fact_miaoshou_analytics_weekly.header_columns,\n            fact_miaoshou_analytics_weekly.data_hash,\n            fact_miaoshou_analytics_weekly.ingest_timestamp,\n            fact_miaoshou_analytics_weekly.currency_code\n           FROM b_class.fact_miaoshou_analytics_weekly\n        UNION ALL\n         SELECT fact_miaoshou_analytics_monthly.platform_code,\n            fact_miaoshou_analytics_monthly.shop_id,\n            fact_miaoshou_analytics_monthly.data_domain,\n            fact_miaoshou_analytics_monthly.granularity,\n            fact_miaoshou_analytics_monthly.metric_date,\n            fact_miaoshou_analytics_monthly.period_start_date,\n            fact_miaoshou_analytics_monthly.period_end_date,\n            fact_miaoshou_analytics_monthly.period_start_time,\n            fact_miaoshou_analytics_monthly.period_end_time,\n            fact_miaoshou_analytics_monthly.raw_data,\n            fact_miaoshou_analytics_monthly.header_columns,\n            fact_miaoshou_analytics_monthly.data_hash,\n            fact_miaoshou_analytics_monthly.ingest_timestamp,\n            fact_miaoshou_analytics_monthly.currency_code\n           FROM b_class.fact_miaoshou_analytics_monthly\n        ), mapped AS (\n         SELECT raw_analytics.platform_code,\n            NULLIF(TRIM(BOTH FROM COALESCE(raw_analytics.shop_id, ''::character varying)), ''::text) AS source_shop_id,\n            NULLIF(TRIM(BOTH FROM COALESCE((raw_analytics.raw_data ->> '店铺'::text), (raw_analytics.raw_data ->> '店铺名'::text), (raw_analytics.raw_data ->> '店铺名称'::text), (raw_analytics.raw_data ->> 'store_name'::text), (raw_analytics.raw_data ->> 'store_label_raw'::text))), ''::text) AS store_label_raw,\n            NULLIF(TRIM(BOTH FROM COALESCE((raw_analytics.raw_data ->> 'platform_shop_id'::text), (raw_analytics.raw_data ->> 'shop_id'::text), (raw_analytics.raw_data ->> '平台店铺ID'::text), (raw_analytics.raw_data ->> '店铺ID'::text))), ''::text) AS source_platform_shop_id,\n            NULLIF(TRIM(BOTH FROM COALESCE((raw_analytics.raw_data ->> 'shop_account_id'::text), (raw_analytics.raw_data ->> 'account_id'::text), (raw_analytics.raw_data ->> '店铺账号ID'::text), (raw_analytics.raw_data ->> '账号ID'::text), (raw_analytics.raw_data ->> 'account'::text))), ''::text) AS source_shop_account_id,\n            raw_analytics.data_domain,\n            raw_analytics.granularity,\n            raw_analytics.metric_date,\n            raw_analytics.period_start_date,\n            raw_analytics.period_end_date,\n            raw_analytics.period_start_time,\n            raw_analytics.period_end_time,\n            COALESCE(\n                CASE\n                    WHEN (lower((COALESCE(raw_analytics.platform_code, ''::character varying))::text) = 'tiktok'::text) THEN (raw_analytics.raw_data ->> '商品访客数'::text)\n                    ELSE NULL::text\n                END, (raw_analytics.raw_data ->> '访客数'::text), (raw_analytics.raw_data ->> '独立访客'::text), (raw_analytics.raw_data ->> '去重页面浏览次数'::text), (raw_analytics.raw_data ->> '店铺页面访问量'::text), (raw_analytics.raw_data ->> 'unique_visitors'::text), (raw_analytics.raw_data ->> 'Unique Visitors'::text), (raw_analytics.raw_data ->> 'uv'::text), (raw_analytics.raw_data ->> 'visitor_count'::text)) AS visitor_count_raw,\n            COALESCE((raw_analytics.raw_data ->> '浏览量'::text), (raw_analytics.raw_data ->> '页面浏览数'::text), (raw_analytics.raw_data ->> '页面浏览次数'::text), (raw_analytics.raw_data ->> 'page_views'::text), (raw_analytics.raw_data ->> 'Page Views'::text), (raw_analytics.raw_data ->> 'views'::text), (raw_analytics.raw_data ->> 'page_view'::text)) AS page_views_raw,\n            COALESCE((raw_analytics.raw_data ->> '曝光次数'::text), (raw_analytics.raw_data ->> 'impressions'::text), (raw_analytics.raw_data ->> 'Impressions'::text)) AS impressions_raw,\n            COALESCE((raw_analytics.raw_data ->> '点击次数'::text), (raw_analytics.raw_data ->> 'clicks'::text), (raw_analytics.raw_data ->> 'Clicks'::text)) AS clicks_raw,\n            COALESCE((raw_analytics.raw_data ->> '点击率'::text), (raw_analytics.raw_data ->> 'click_rate'::text), (raw_analytics.raw_data ->> 'Click Rate'::text), (raw_analytics.raw_data ->> 'CTR'::text)) AS click_rate_raw,\n            COALESCE((raw_analytics.raw_data ->> '转化率'::text), (raw_analytics.raw_data ->> 'conversion_rate'::text), (raw_analytics.raw_data ->> 'Conversion Rate'::text), (raw_analytics.raw_data ->> 'CVR'::text)) AS conversion_rate_raw,\n            COALESCE((raw_analytics.raw_data ->> '订单数'::text), (raw_analytics.raw_data ->> '订单数量'::text), (raw_analytics.raw_data ->> 'order_count'::text), (raw_analytics.raw_data ->> 'Order Count'::text)) AS order_count_raw,\n            COALESCE((raw_analytics.raw_data ->> 'SKU 订单数'::text), (raw_analytics.raw_data ->> 'sku_order_count'::text), (raw_analytics.raw_data ->> 'SKU Order Count'::text)) AS sku_order_count_raw,\n            COALESCE((raw_analytics.raw_data ->> 'GMV'::text), (raw_analytics.raw_data ->> 'gmv'::text)) AS gmv_raw,\n            COALESCE((raw_analytics.raw_data ->> '总成交额'::text), (raw_analytics.raw_data ->> '成交金额'::text), (raw_analytics.raw_data ->> 'sales_amount'::text)) AS total_transaction_amount_raw,\n            COALESCE((raw_analytics.raw_data ->> '商品访客数'::text), (raw_analytics.raw_data ->> 'product_visitor_count'::text), (raw_analytics.raw_data ->> 'Product Visitor Count'::text)) AS product_visitor_count_raw,\n            COALESCE((raw_analytics.raw_data ->> '跳出率'::text), (raw_analytics.raw_data ->> 'bounce_rate'::text), (raw_analytics.raw_data ->> 'Bounce Rate'::text)) AS bounce_rate_raw,\n            raw_analytics.raw_data,\n            raw_analytics.header_columns,\n            raw_analytics.data_hash,\n            raw_analytics.ingest_timestamp,\n            raw_analytics.currency_code\n           FROM raw_analytics\n        ), resolved AS (\n         SELECT m.platform_code,\n                CASE\n                    WHEN (resolved_candidate.resolved_shop_id IS NOT NULL) THEN resolved_candidate.resolved_shop_id\n                    WHEN (COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id) IS NULL) THEN 'unknown'::text\n                    ELSE COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id)\n                END AS shop_id,\n            COALESCE(m.source_shop_id, m.store_label_raw) AS raw_shop_id,\n            m.store_label_raw,\n            resolved_candidate.resolved_shop_account_id,\n                CASE\n                    WHEN (resolved_candidate.resolved_shop_id IS NOT NULL) THEN resolved_candidate.resolution_method\n                    WHEN (COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id) IS NULL) THEN 'missing_identity'::character varying\n                    ELSE 'unclaimed_identity'::character varying\n                END AS resolution_method,\n            COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id) AS identity_source_value,\n            m.data_domain,\n            m.granularity,\n            m.metric_date,\n            m.period_start_date,\n            m.period_end_date,\n            m.period_start_time,\n            m.period_end_time,\n            m.visitor_count_raw,\n            m.page_views_raw,\n            m.impressions_raw,\n            m.clicks_raw,\n            m.click_rate_raw,\n            m.conversion_rate_raw,\n            m.order_count_raw,\n            m.sku_order_count_raw,\n            m.gmv_raw,\n            m.total_transaction_amount_raw,\n            m.product_visitor_count_raw,\n            m.bounce_rate_raw,\n            m.raw_data,\n            m.header_columns,\n            m.data_hash,\n            m.ingest_timestamp,\n            m.currency_code\n           FROM (mapped m\n             LEFT JOIN LATERAL ( SELECT c.resolved_shop_id,\n                    c.resolved_shop_account_id,\n                    c.resolution_method,\n                    c.resolution_priority\n                   FROM (( VALUES (lower(COALESCE(m.source_platform_shop_id, ''::text))), (lower(COALESCE(m.source_shop_account_id, ''::text))), (lower(COALESCE(m.source_shop_id, ''::text))), (regexp_replace(regexp_replace(lower(TRIM(BOTH FROM COALESCE(m.source_shop_id, ''::text))), '^(shopee|tiktok\\s*shop|tiktok|tk|miaoshou|amazon|lazada)\\s*'::text, ''::text, 'i'::text), '[[:space:]_()/-]+'::text, ''::text, 'g'::text)), (regexp_replace(regexp_replace(lower(TRIM(BOTH FROM COALESCE(m.store_label_raw, ''::text))), '^(shopee|tiktok\\s*shop|tiktok|tk|miaoshou|amazon|lazada)\\s*'::text, ''::text, 'i'::text), '[[:space:]_()/-]+'::text, ''::text, 'g'::text))) candidate(identity_value_normalized)\n                     JOIN semantic.shop_identity_resolution_candidates c ON (((c.platform_code = lower((COALESCE(m.platform_code, ''::character varying))::text)) AND (c.identity_value_normalized = candidate.identity_value_normalized))))\n                  WHERE (NULLIF(candidate.identity_value_normalized, ''::text) IS NOT NULL)\n                  ORDER BY c.resolution_priority, c.resolved_shop_id\n                 LIMIT 1) resolved_candidate ON (true))\n        ), cleaned AS (\n         SELECT resolved.platform_code,\n            resolved.shop_id,\n            resolved.raw_shop_id,\n            resolved.store_label_raw,\n            resolved.resolved_shop_account_id,\n            resolved.resolution_method,\n            resolved.identity_source_value,\n            resolved.data_domain,\n            resolved.granularity,\n            resolved.metric_date,\n            resolved.period_start_date,\n            resolved.period_end_date,\n            resolved.period_start_time,\n            resolved.period_end_time,\n                CASE\n                    WHEN (resolved.visitor_count_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.visitor_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS visitor_count,\n                CASE\n                    WHEN (resolved.page_views_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.page_views_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS page_views,\n                CASE\n                    WHEN (resolved.impressions_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.impressions_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS impressions,\n                CASE\n                    WHEN (resolved.clicks_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.clicks_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS clicks,\n                CASE\n                    WHEN (resolved.click_rate_raw IS NULL) THEN NULL::numeric\n                    ELSE ((NULLIF(regexp_replace(replace(replace(replace(replace(replace(resolved.click_rate_raw, '%'::text, ''::text), ','::text, '.'::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric / 100.0)\n                END AS click_rate,\n                CASE\n                    WHEN (resolved.conversion_rate_raw IS NULL) THEN NULL::numeric\n                    ELSE ((NULLIF(regexp_replace(replace(replace(replace(replace(replace(resolved.conversion_rate_raw, '%'::text, ''::text), ','::text, '.'::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric / 100.0)\n                END AS conversion_rate,\n                CASE\n                    WHEN (resolved.order_count_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.order_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS order_count,\n                CASE\n                    WHEN (resolved.sku_order_count_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.sku_order_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS sku_order_count,\n                CASE\n                    WHEN (resolved.gmv_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.gmv_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS gmv,\n                CASE\n                    WHEN (resolved.total_transaction_amount_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.total_transaction_amount_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS total_transaction_amount,\n                CASE\n                    WHEN (resolved.product_visitor_count_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(resolved.product_visitor_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS product_visitor_count,\n                CASE\n                    WHEN (resolved.bounce_rate_raw IS NULL) THEN NULL::numeric\n                    ELSE ((NULLIF(regexp_replace(replace(replace(replace(replace(replace(resolved.bounce_rate_raw, '%'::text, ''::text), ','::text, '.'::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric / 100.0)\n                END AS bounce_rate,\n            resolved.raw_data,\n            resolved.header_columns,\n            resolved.data_hash,\n            resolved.ingest_timestamp,\n            resolved.currency_code\n           FROM resolved\n        ), deduplicated AS (\n         SELECT cleaned.platform_code,\n            cleaned.shop_id,\n            cleaned.raw_shop_id,\n            cleaned.store_label_raw,\n            cleaned.resolved_shop_account_id,\n            cleaned.resolution_method,\n            cleaned.identity_source_value,\n            cleaned.data_domain,\n            cleaned.granularity,\n            cleaned.metric_date,\n            cleaned.period_start_date,\n            cleaned.period_end_date,\n            cleaned.period_start_time,\n            cleaned.period_end_time,\n            cleaned.visitor_count,\n            cleaned.page_views,\n            cleaned.impressions,\n            cleaned.clicks,\n            cleaned.click_rate,\n            cleaned.conversion_rate,\n            cleaned.order_count,\n            cleaned.sku_order_count,\n            cleaned.gmv,\n            cleaned.total_transaction_amount,\n            cleaned.product_visitor_count,\n            cleaned.bounce_rate,\n            cleaned.raw_data,\n            cleaned.header_columns,\n            cleaned.data_hash,\n            cleaned.ingest_timestamp,\n            cleaned.currency_code,\n            row_number() OVER (PARTITION BY cleaned.platform_code, cleaned.shop_id, cleaned.data_hash ORDER BY\n                CASE cleaned.granularity\n                    WHEN 'daily'::text THEN 1\n                    WHEN 'weekly'::text THEN 2\n                    WHEN 'monthly'::text THEN 3\n                    ELSE 9\n                END, cleaned.ingest_timestamp DESC) AS rn\n           FROM cleaned\n        )\n SELECT deduplicated.platform_code,\n    deduplicated.shop_id,\n    deduplicated.raw_shop_id,\n    deduplicated.store_label_raw,\n    deduplicated.resolved_shop_account_id,\n    deduplicated.resolution_method,\n    deduplicated.identity_source_value,\n    deduplicated.data_domain,\n    deduplicated.granularity,\n    deduplicated.metric_date,\n    deduplicated.period_start_date,\n    deduplicated.period_end_date,\n    deduplicated.period_start_time,\n    deduplicated.period_end_time,\n    COALESCE(deduplicated.visitor_count, (0)::numeric) AS visitor_count,\n    COALESCE(deduplicated.page_views, (0)::numeric) AS page_views,\n    COALESCE(deduplicated.impressions, (0)::numeric) AS impressions,\n    COALESCE(deduplicated.clicks, (0)::numeric) AS clicks,\n    COALESCE(deduplicated.click_rate, (0)::numeric) AS click_rate,\n    COALESCE(deduplicated.conversion_rate, (0)::numeric) AS conversion_rate,\n    COALESCE(deduplicated.order_count, (0)::numeric) AS order_count,\n    COALESCE(deduplicated.sku_order_count, (0)::numeric) AS sku_order_count,\n    COALESCE(deduplicated.gmv, (0)::numeric) AS gmv,\n    COALESCE(deduplicated.total_transaction_amount, (0)::numeric) AS total_transaction_amount,\n    COALESCE(deduplicated.product_visitor_count, (0)::numeric) AS product_visitor_count,\n    COALESCE(deduplicated.bounce_rate, (0)::numeric) AS bounce_rate,\n    deduplicated.raw_data,\n    deduplicated.header_columns,\n    deduplicated.data_hash,\n    deduplicated.ingest_timestamp,\n    deduplicated.currency_code\n   FROM deduplicated\n  WHERE (deduplicated.rn = 1)",
    "CREATE VIEW mart.shop_day_kpi AS\n WITH daily_orders AS (\n         SELECT fact_orders_atomic.metric_date AS period_date,\n            fact_orders_atomic.platform_code,\n            fact_orders_atomic.shop_id,\n            sum(fact_orders_atomic.paid_amount) AS gmv,\n                CASE\n                    WHEN (count(*) > 0) THEN count(DISTINCT fact_orders_atomic.order_id)\n                    ELSE NULL::bigint\n                END AS order_count,\n            sum(fact_orders_atomic.product_quantity) AS total_items,\n            sum(fact_orders_atomic.profit) AS profit,\n            count(*) AS source_row_count\n           FROM semantic.fact_orders_atomic\n          WHERE ((fact_orders_atomic.granularity)::text = 'daily'::text)\n          GROUP BY fact_orders_atomic.metric_date, fact_orders_atomic.platform_code, fact_orders_atomic.shop_id\n        ), daily_traffic AS (\n         SELECT fact_analytics_atomic.metric_date AS period_date,\n            fact_analytics_atomic.platform_code,\n            fact_analytics_atomic.shop_id,\n            sum(fact_analytics_atomic.visitor_count) AS visitor_count,\n            sum(fact_analytics_atomic.page_views) AS page_views,\n            sum(fact_analytics_atomic.impressions) AS impressions,\n            count(*) AS source_row_count\n           FROM semantic.fact_analytics_atomic\n          WHERE ((fact_analytics_atomic.granularity)::text = 'daily'::text)\n          GROUP BY fact_analytics_atomic.metric_date, fact_analytics_atomic.platform_code, fact_analytics_atomic.shop_id\n        )\n SELECT COALESCE(o.period_date, t.period_date) AS period_date,\n    COALESCE(o.platform_code, t.platform_code) AS platform_code,\n    COALESCE(o.shop_id, t.shop_id) AS shop_id,\n        CASE\n            WHEN (o.source_row_count > 0) THEN o.gmv\n            ELSE NULL::numeric\n        END AS gmv,\n        CASE\n            WHEN (o.source_row_count > 0) THEN o.order_count\n            ELSE NULL::bigint\n        END AS order_count,\n        CASE\n            WHEN (t.source_row_count > 0) THEN t.visitor_count\n            ELSE NULL::numeric\n        END AS visitor_count,\n        CASE\n            WHEN (t.source_row_count > 0) THEN t.page_views\n            ELSE NULL::numeric\n        END AS page_views,\n        CASE\n            WHEN (t.source_row_count > 0) THEN t.impressions\n            ELSE NULL::numeric\n        END AS impressions,\n        CASE\n            WHEN ((o.source_row_count > 0) AND (t.source_row_count > 0) AND (t.visitor_count > (0)::numeric)) THEN round((((o.order_count)::numeric * 100.0) / t.visitor_count), 2)\n            WHEN ((o.source_row_count > 0) AND (t.source_row_count > 0) AND (t.visitor_count = (0)::numeric) AND (o.order_count = 0)) THEN (0)::numeric\n            ELSE NULL::numeric\n        END AS conversion_rate,\n        CASE\n            WHEN ((o.source_row_count > 0) AND (t.source_row_count > 0) AND (t.visitor_count > (0)::numeric)) THEN round((((o.order_count)::numeric * 100.0) / t.visitor_count), 2)\n            WHEN ((o.source_row_count > 0) AND (t.source_row_count > 0) AND (t.visitor_count = (0)::numeric) AND (o.order_count = 0)) THEN (0)::numeric\n            ELSE NULL::numeric\n        END AS uv_conversion_rate,\n        CASE\n            WHEN ((o.source_row_count > 0) AND (t.source_row_count > 0) AND (t.page_views > (0)::numeric)) THEN round((((o.order_count)::numeric * 100.0) / t.page_views), 2)\n            WHEN ((o.source_row_count > 0) AND (t.source_row_count > 0) AND (t.page_views = (0)::numeric) AND (o.order_count = 0)) THEN (0)::numeric\n            ELSE NULL::numeric\n        END AS pv_conversion_rate,\n        CASE\n            WHEN ((t.source_row_count > 0) AND (t.impressions > (0)::numeric)) THEN round(((t.visitor_count * 100.0) / t.impressions), 2)\n            WHEN ((t.source_row_count > 0) AND (t.visitor_count = (0)::numeric) AND (t.impressions = (0)::numeric)) THEN (0)::numeric\n            ELSE NULL::numeric\n        END AS visit_rate,\n        CASE\n            WHEN ((t.source_row_count > 0) AND (t.visitor_count > (0)::numeric)) THEN round((t.page_views / t.visitor_count), 2)\n            WHEN ((t.source_row_count > 0) AND (t.page_views = (0)::numeric) AND (t.visitor_count = (0)::numeric)) THEN (0)::numeric\n            ELSE NULL::numeric\n        END AS browse_depth,\n        CASE\n            WHEN ((o.source_row_count > 0) AND (t.source_row_count > 0) AND (t.impressions > (0)::numeric)) THEN round((((o.order_count)::numeric * 100.0) / t.impressions), 2)\n            WHEN ((o.source_row_count > 0) AND (t.source_row_count > 0) AND (o.order_count = 0) AND (t.impressions = (0)::numeric)) THEN (0)::numeric\n            ELSE NULL::numeric\n        END AS exposure_order_rate,\n        CASE\n            WHEN ((o.source_row_count > 0) AND (o.order_count > 0)) THEN round((o.gmv / (o.order_count)::numeric), 2)\n            WHEN ((o.source_row_count > 0) AND (o.order_count = 0) AND (o.gmv = (0)::numeric)) THEN (0)::numeric\n            ELSE NULL::numeric\n        END AS avg_order_value,\n        CASE\n            WHEN ((o.source_row_count > 0) AND (o.order_count > 0)) THEN round((o.total_items / (o.order_count)::numeric), 2)\n            WHEN ((o.source_row_count > 0) AND (o.order_count = 0) AND (o.total_items = (0)::numeric)) THEN (0)::numeric\n            ELSE NULL::numeric\n        END AS attach_rate,\n        CASE\n            WHEN (o.source_row_count > 0) THEN o.total_items\n            ELSE NULL::numeric\n        END AS total_items,\n        CASE\n            WHEN (o.source_row_count > 0) THEN o.profit\n            ELSE NULL::numeric\n        END AS profit\n   FROM (daily_orders o\n     FULL JOIN daily_traffic t ON (((o.period_date = t.period_date) AND ((o.platform_code)::text = (t.platform_code)::text) AND (COALESCE(o.shop_id, ''::text) = COALESCE(t.shop_id, ''::text)))))",
    "CREATE MATERIALIZED VIEW semantic.fact_analytics_monthly_atomic_mv AS\n WITH raw_monthly_traffic AS MATERIALIZED (\n         SELECT fact_shopee_analytics_monthly.platform_code,\n            fact_shopee_analytics_monthly.shop_id,\n            fact_shopee_analytics_monthly.metric_date,\n            fact_shopee_analytics_monthly.raw_data,\n            fact_shopee_analytics_monthly.data_hash,\n            fact_shopee_analytics_monthly.ingest_timestamp\n           FROM b_class.fact_shopee_analytics_monthly\n        UNION ALL\n         SELECT fact_tiktok_analytics_monthly.platform_code,\n            fact_tiktok_analytics_monthly.shop_id,\n            fact_tiktok_analytics_monthly.metric_date,\n            fact_tiktok_analytics_monthly.raw_data,\n            fact_tiktok_analytics_monthly.data_hash,\n            fact_tiktok_analytics_monthly.ingest_timestamp\n           FROM b_class.fact_tiktok_analytics_monthly\n        UNION ALL\n         SELECT fact_miaoshou_analytics_monthly.platform_code,\n            fact_miaoshou_analytics_monthly.shop_id,\n            fact_miaoshou_analytics_monthly.metric_date,\n            fact_miaoshou_analytics_monthly.raw_data,\n            fact_miaoshou_analytics_monthly.data_hash,\n            fact_miaoshou_analytics_monthly.ingest_timestamp\n           FROM b_class.fact_miaoshou_analytics_monthly\n        ), mapped_monthly_traffic AS MATERIALIZED (\n         SELECT raw_monthly_traffic.metric_date,\n            raw_monthly_traffic.platform_code,\n            NULLIF(TRIM(BOTH FROM COALESCE(raw_monthly_traffic.shop_id, ''::character varying)), ''::text) AS source_shop_id,\n            NULLIF(TRIM(BOTH FROM COALESCE((raw_monthly_traffic.raw_data ->> '店铺'::text), (raw_monthly_traffic.raw_data ->> '店铺名'::text), (raw_monthly_traffic.raw_data ->> '店铺名称'::text), (raw_monthly_traffic.raw_data ->> 'store_name'::text), (raw_monthly_traffic.raw_data ->> 'store_label_raw'::text))), ''::text) AS store_label_raw,\n            NULLIF(TRIM(BOTH FROM COALESCE((raw_monthly_traffic.raw_data ->> 'platform_shop_id'::text), (raw_monthly_traffic.raw_data ->> '平台店铺ID'::text), (raw_monthly_traffic.raw_data ->> '店铺ID'::text))), ''::text) AS source_platform_shop_id,\n            NULLIF(TRIM(BOTH FROM COALESCE((raw_monthly_traffic.raw_data ->> 'shop_account_id'::text), (raw_monthly_traffic.raw_data ->> 'account_id'::text), (raw_monthly_traffic.raw_data ->> '店铺账号ID'::text), (raw_monthly_traffic.raw_data ->> '账号ID'::text), (raw_monthly_traffic.raw_data ->> 'account'::text))), ''::text) AS source_shop_account_id,\n            COALESCE(\n                CASE\n                    WHEN (lower((COALESCE(raw_monthly_traffic.platform_code, ''::character varying))::text) = 'tiktok'::text) THEN (raw_monthly_traffic.raw_data ->> '商品访客数'::text)\n                    ELSE NULL::text\n                END, (raw_monthly_traffic.raw_data ->> '访客数'::text), (raw_monthly_traffic.raw_data ->> '独立访客'::text), (raw_monthly_traffic.raw_data ->> '店铺页面访问量'::text), (raw_monthly_traffic.raw_data ->> 'unique_visitors'::text), (raw_monthly_traffic.raw_data ->> 'Unique Visitors'::text), (raw_monthly_traffic.raw_data ->> 'uv'::text), (raw_monthly_traffic.raw_data ->> 'visitor_count'::text)) AS visitor_count_raw,\n            COALESCE((raw_monthly_traffic.raw_data ->> '商品访客数'::text), (raw_monthly_traffic.raw_data ->> 'product_visitor_count'::text), (raw_monthly_traffic.raw_data ->> 'Product Visitor Count'::text)) AS product_visitor_count_raw,\n            COALESCE((raw_monthly_traffic.raw_data ->> '浏览量'::text), (raw_monthly_traffic.raw_data ->> '页面浏览数'::text), (raw_monthly_traffic.raw_data ->> '页面浏览次数'::text), (raw_monthly_traffic.raw_data ->> 'page_views'::text), (raw_monthly_traffic.raw_data ->> 'Page Views'::text), (raw_monthly_traffic.raw_data ->> 'views'::text), (raw_monthly_traffic.raw_data ->> 'page_view'::text)) AS page_views_raw,\n            COALESCE((raw_monthly_traffic.raw_data ->> '曝光次数'::text), (raw_monthly_traffic.raw_data ->> '鏇濆厜娆℃暟'::text), (raw_monthly_traffic.raw_data ->> 'impressions'::text), (raw_monthly_traffic.raw_data ->> 'Impressions'::text)) AS impressions_raw,\n            COALESCE((raw_monthly_traffic.raw_data ->> '订单数'::text), (raw_monthly_traffic.raw_data ->> '订单数量'::text), (raw_monthly_traffic.raw_data ->> 'order_count'::text), (raw_monthly_traffic.raw_data ->> 'Order Count'::text)) AS order_count_raw,\n            COALESCE((raw_monthly_traffic.raw_data ->> 'SKU 订单数'::text), (raw_monthly_traffic.raw_data ->> 'sku_order_count'::text), (raw_monthly_traffic.raw_data ->> 'SKU Order Count'::text)) AS sku_order_count_raw,\n            COALESCE((raw_monthly_traffic.raw_data ->> 'GMV'::text), (raw_monthly_traffic.raw_data ->> 'gmv'::text)) AS gmv_raw,\n            COALESCE((raw_monthly_traffic.raw_data ->> '总成交额'::text), (raw_monthly_traffic.raw_data ->> '成交金额'::text), (raw_monthly_traffic.raw_data ->> 'sales_amount'::text)) AS total_transaction_amount_raw,\n            raw_monthly_traffic.data_hash,\n            raw_monthly_traffic.ingest_timestamp\n           FROM raw_monthly_traffic\n        ), normalized_monthly_traffic AS MATERIALIZED (\n         SELECT mapped_monthly_traffic.metric_date,\n            mapped_monthly_traffic.platform_code,\n            mapped_monthly_traffic.source_shop_id,\n            mapped_monthly_traffic.store_label_raw,\n            mapped_monthly_traffic.source_platform_shop_id,\n            mapped_monthly_traffic.source_shop_account_id,\n                CASE\n                    WHEN (mapped_monthly_traffic.visitor_count_raw IS NULL) THEN NULL::numeric\n                    ELSE\n                    CASE\n                        WHEN (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.visitor_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text) = ANY (ARRAY['-'::text, '.'::text, '-.'::text])) THEN NULL::numeric\n                        ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.visitor_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                    END\n                END AS visitor_count,\n                CASE\n                    WHEN (mapped_monthly_traffic.product_visitor_count_raw IS NULL) THEN NULL::numeric\n                    ELSE\n                    CASE\n                        WHEN (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.product_visitor_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text) = ANY (ARRAY['-'::text, '.'::text, '-.'::text])) THEN NULL::numeric\n                        ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.product_visitor_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                    END\n                END AS product_visitor_count,\n                CASE\n                    WHEN (mapped_monthly_traffic.page_views_raw IS NULL) THEN NULL::numeric\n                    ELSE\n                    CASE\n                        WHEN (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.page_views_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text) = ANY (ARRAY['-'::text, '.'::text, '-.'::text])) THEN NULL::numeric\n                        ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.page_views_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                    END\n                END AS page_views,\n                CASE\n                    WHEN (mapped_monthly_traffic.impressions_raw IS NULL) THEN NULL::numeric\n                    ELSE\n                    CASE\n                        WHEN (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.impressions_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text) = ANY (ARRAY['-'::text, '.'::text, '-.'::text])) THEN NULL::numeric\n                        ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.impressions_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                    END\n                END AS impressions,\n                CASE\n                    WHEN (mapped_monthly_traffic.order_count_raw IS NULL) THEN NULL::numeric\n                    ELSE\n                    CASE\n                        WHEN (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.order_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text) = ANY (ARRAY['-'::text, '.'::text, '-.'::text])) THEN NULL::numeric\n                        ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.order_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                    END\n                END AS order_count,\n                CASE\n                    WHEN (mapped_monthly_traffic.sku_order_count_raw IS NULL) THEN NULL::numeric\n                    ELSE\n                    CASE\n                        WHEN (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.sku_order_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text) = ANY (ARRAY['-'::text, '.'::text, '-.'::text])) THEN NULL::numeric\n                        ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.sku_order_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                    END\n                END AS sku_order_count,\n                CASE\n                    WHEN (mapped_monthly_traffic.gmv_raw IS NULL) THEN NULL::numeric\n                    ELSE\n                    CASE\n                        WHEN (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.gmv_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text) = ANY (ARRAY['-'::text, '.'::text, '-.'::text])) THEN NULL::numeric\n                        ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.gmv_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                    END\n                END AS gmv,\n                CASE\n                    WHEN (mapped_monthly_traffic.total_transaction_amount_raw IS NULL) THEN NULL::numeric\n                    ELSE\n                    CASE\n                        WHEN (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.total_transaction_amount_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text) = ANY (ARRAY['-'::text, '.'::text, '-.'::text])) THEN NULL::numeric\n                        ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped_monthly_traffic.total_transaction_amount_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                    END\n                END AS total_transaction_amount,\n            array_remove(ARRAY[lower(COALESCE(mapped_monthly_traffic.source_platform_shop_id, ''::text)), lower(COALESCE(mapped_monthly_traffic.source_shop_account_id, ''::text)),\n                CASE\n                    WHEN (lower(COALESCE(mapped_monthly_traffic.source_shop_id, ''::text)) <> ALL (ARRAY['xihong'::text, 'unknown'::text, 'none'::text])) THEN lower(COALESCE(mapped_monthly_traffic.source_shop_id, ''::text))\n                    ELSE NULL::text\n                END,\n                CASE\n                    WHEN (lower(COALESCE(mapped_monthly_traffic.source_shop_id, ''::text)) <> ALL (ARRAY['xihong'::text, 'unknown'::text, 'none'::text])) THEN regexp_replace(regexp_replace(lower(TRIM(BOTH FROM COALESCE(mapped_monthly_traffic.source_shop_id, ''::text))), '^(shopee|tiktok\\s*shop|tiktok|tk|miaoshou|amazon|lazada)\\s*'::text, ''::text, 'i'::text), '[[:space:]_()/-]+'::text, ''::text, 'g'::text)\n                    ELSE NULL::text\n                END, regexp_replace(regexp_replace(lower(TRIM(BOTH FROM COALESCE(mapped_monthly_traffic.store_label_raw, ''::text))), '^(shopee|tiktok\\s*shop|tiktok|tk|miaoshou|amazon|lazada)\\s*'::text, ''::text, 'i'::text), '[[:space:]_()/-]+'::text, ''::text, 'g'::text)], ''::text) AS normalized_identity_candidates,\n            mapped_monthly_traffic.data_hash,\n            mapped_monthly_traffic.ingest_timestamp\n           FROM mapped_monthly_traffic\n        ), resolved_monthly_traffic AS MATERIALIZED (\n         SELECT m.metric_date,\n            m.platform_code,\n                CASE\n                    WHEN (resolved.resolved_shop_id IS NOT NULL) THEN COALESCE(NULLIF(TRIM(BOTH FROM canonical.platform_shop_id), ''::text), resolved.resolved_shop_id)\n                    WHEN (COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id) IS NULL) THEN 'unknown'::text\n                    ELSE COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id)\n                END AS shop_id,\n            COALESCE(m.source_shop_id, m.store_label_raw) AS raw_shop_id,\n            m.store_label_raw,\n            resolved.resolved_shop_account_id,\n                CASE\n                    WHEN (resolved.resolved_shop_id IS NOT NULL) THEN resolved.resolution_method\n                    WHEN (COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id) IS NULL) THEN 'missing_identity'::character varying\n                    ELSE 'unclaimed_identity'::character varying\n                END AS resolution_method,\n                CASE\n                    WHEN (resolved.resolved_shop_id IS NOT NULL) THEN resolved.identity_source_value\n                    ELSE COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id)\n                END AS identity_source_value,\n                CASE\n                    WHEN (resolved.resolved_shop_account_id IS NOT NULL) THEN COALESCE(NULLIF(TRIM(BOTH FROM canonical.platform_shop_id), ''::text), resolved.resolved_shop_id)\n                    ELSE NULL::text\n                END AS canonical_shop_id,\n                CASE\n                    WHEN (COALESCE(m.source_platform_shop_id, m.source_shop_account_id, m.store_label_raw, m.source_shop_id) IS NULL) THEN 'missing_identity'::text\n                    WHEN (resolved.resolved_shop_account_id IS NULL) THEN 'unresolved_shop_account'::text\n                    WHEN ((resolved.resolved_shop_account_id IS NOT NULL) AND (canonical.shop_account_id IS NULL)) THEN 'unresolved_shop_account'::text\n                    WHEN ((resolved.resolved_shop_account_id IS NOT NULL) AND (lower((COALESCE(m.platform_code, ''::character varying))::text) = 'shopee'::text) AND (NULLIF(TRIM(BOTH FROM canonical.platform_shop_id), ''::text) IS NULL)) THEN 'missing_required_platform_shop_id'::text\n                    ELSE NULL::text\n                END AS identity_warning_code,\n            m.visitor_count,\n            m.product_visitor_count,\n            m.page_views,\n            m.impressions,\n            m.order_count,\n            m.sku_order_count,\n            m.gmv,\n            m.total_transaction_amount,\n            m.data_hash,\n            m.ingest_timestamp\n           FROM ((normalized_monthly_traffic m\n             LEFT JOIN LATERAL ( SELECT c.resolved_shop_id,\n                    c.resolved_shop_account_id,\n                    c.resolution_method,\n                    c.resolution_priority,\n                    c.identity_source_value\n                   FROM semantic.shop_identity_resolution_candidates c\n                  WHERE ((c.platform_code = lower((COALESCE(m.platform_code, ''::character varying))::text)) AND (c.identity_value_normalized = ANY (m.normalized_identity_candidates)))\n                  ORDER BY c.resolution_priority, c.resolved_shop_id\n                 LIMIT 1) resolved ON (true))\n             LEFT JOIN core.shop_accounts canonical ON (((lower((COALESCE(canonical.platform, ''::character varying))::text) = lower((COALESCE(m.platform_code, ''::character varying))::text)) AND ((canonical.shop_account_id)::text = resolved.resolved_shop_account_id))))\n        ), deduplicated_monthly_traffic AS (\n         SELECT resolved_monthly_traffic.metric_date,\n            resolved_monthly_traffic.platform_code,\n            resolved_monthly_traffic.shop_id,\n            resolved_monthly_traffic.raw_shop_id,\n            resolved_monthly_traffic.store_label_raw,\n            resolved_monthly_traffic.resolved_shop_account_id,\n            resolved_monthly_traffic.resolution_method,\n            resolved_monthly_traffic.identity_source_value,\n            resolved_monthly_traffic.canonical_shop_id,\n            resolved_monthly_traffic.identity_warning_code,\n            resolved_monthly_traffic.visitor_count,\n            resolved_monthly_traffic.product_visitor_count,\n            resolved_monthly_traffic.page_views,\n            resolved_monthly_traffic.impressions,\n            resolved_monthly_traffic.order_count,\n            resolved_monthly_traffic.sku_order_count,\n            resolved_monthly_traffic.gmv,\n            resolved_monthly_traffic.total_transaction_amount,\n            resolved_monthly_traffic.data_hash,\n            resolved_monthly_traffic.ingest_timestamp,\n            row_number() OVER (PARTITION BY resolved_monthly_traffic.platform_code, COALESCE(resolved_monthly_traffic.shop_id, ''::text), resolved_monthly_traffic.data_hash ORDER BY resolved_monthly_traffic.ingest_timestamp DESC) AS rn\n           FROM resolved_monthly_traffic\n        )\n SELECT deduplicated_monthly_traffic.metric_date,\n    deduplicated_monthly_traffic.platform_code,\n    deduplicated_monthly_traffic.shop_id,\n    deduplicated_monthly_traffic.raw_shop_id,\n    deduplicated_monthly_traffic.store_label_raw,\n    deduplicated_monthly_traffic.resolved_shop_account_id,\n    deduplicated_monthly_traffic.resolution_method,\n    deduplicated_monthly_traffic.identity_source_value,\n    deduplicated_monthly_traffic.canonical_shop_id,\n    deduplicated_monthly_traffic.identity_warning_code,\n    deduplicated_monthly_traffic.visitor_count,\n    deduplicated_monthly_traffic.product_visitor_count,\n    deduplicated_monthly_traffic.page_views,\n    deduplicated_monthly_traffic.impressions,\n    deduplicated_monthly_traffic.order_count,\n    deduplicated_monthly_traffic.sku_order_count,\n    deduplicated_monthly_traffic.gmv,\n    deduplicated_monthly_traffic.total_transaction_amount,\n    deduplicated_monthly_traffic.data_hash,\n    deduplicated_monthly_traffic.ingest_timestamp\n   FROM deduplicated_monthly_traffic\n  WHERE (deduplicated_monthly_traffic.rn = 1)\n  WITH NO DATA",
