    "CREATE SEQUENCE finance.tax_vouchers_voucher_id_seq\n    AS integer\n    START WITH 1\n    INCREMENT BY 1\n    NO MINVALUE\n    NO MAXVALUE\n    CACHE 1",
    "ALTER SEQUENCE finance.tax_vouchers_voucher_id_seq OWNED BY finance.tax_vouchers.voucher_id",
    "CREATE TABLE finance.three_way_match_log (\n    match_id integer NOT NULL,\n    po_line_id integer NOT NULL,\n    grn_line_id integer,\n    invoice_line_id integer,\n    match_status character varying(32) NOT NULL,\n    variance_qty integer,\n    variance_amt double precision,\n    variance_reason text,\n    approved_by character varying(64),\n    approved_at timestamp with time zone,\n    created_at timestamp with time zone DEFAULT now() NOT NULL\n)",
    "CREATE SEQUENCE finance.three_way_match_log_match_id_seq\n    AS integer\n    START WITH 1\n    INCREMENT BY 1\n    NO MINVALUE\n    NO MAXVALUE\n    CACHE 1",
    "ALTER SEQUENCE finance.three_way_match_log_match_id_seq OWNED BY finance.three_way_match_log.match_id",
    "CREATE TABLE mart.inventory_age_history (\n    snapshot_date date NOT NULL,\n    platform_code character varying(64) NOT NULL,\n    sku_key character varying(255) NOT NULL,\n    platform_sku character varying(255),\n    product_sku character varying(255),\n    sku_id character varying(255),\n    product_id character varying(255),\n    product_name text,\n    current_qty bigint NOT NULL,\n    previous_qty bigint,\n    qty_delta bigint,\n    age_anchor_date date,\n    age_days integer,\n    bucket character varying(32),\n    reset_reason character varying(64) NOT NULL,\n    on_hand_qty bigint,\n    inventory_value numeric(18,2) DEFAULT 0 NOT NULL,\n    warehouse_count integer DEFAULT 0 NOT NULL,\n    last_ingest_timestamp timestamp with time zone,\n    created_at timestamp with time zone DEFAULT now() NOT NULL,\n    updated_at timestamp with time zone DEFAULT now() NOT NULL\n)",
    "CREATE MATERIALIZED VIEW mart.inventory_backlog_base_mv AS\n WITH latest_snapshot AS (\n         SELECT inventory_snapshot_latest.snapshot_date,\n            inventory_snapshot_latest.platform_code,\n            NULL::text AS shop_id,\n            inventory_snapshot_latest.product_id,\n            inventory_snapshot_latest.product_name,\n            inventory_snapshot_latest.platform_sku,\n            inventory_snapshot_latest.product_sku,\n            inventory_snapshot_latest.warehouse_name,\n            inventory_snapshot_latest.available_stock,\n            inventory_snapshot_latest.on_hand_stock,\n            inventory_snapshot_latest.inventory_value\n           FROM mart.inventory_snapshot_latest\n        ), snapshot_change AS (\n         SELECT inventory_snapshot_change.snapshot_date,\n            inventory_snapshot_change.platform_code,\n            inventory_snapshot_change.shop_id,\n            inventory_snapshot_change.product_id,\n            inventory_snapshot_change.product_name,\n            inventory_snapshot_change.platform_sku,\n            inventory_snapshot_change.product_sku,\n            inventory_snapshot_change.warehouse_name,\n            inventory_snapshot_change.stock_delta,\n            inventory_snapshot_change.inventory_value_delta,\n            inventory_snapshot_change.is_stagnant,\n            inventory_snapshot_change.snapshot_gap_days,\n            inventory_snapshot_change.estimated_stagnant_days,\n            inventory_snapshot_change.stagnant_snapshot_count\n           FROM mart.inventory_snapshot_change\n        ), sales_30d AS (\n         SELECT fact_orders_atomic.platform_code,\n            fact_orders_atomic.platform_sku,\n            fact_orders_atomic.product_sku,\n            COALESCE(sum(fact_orders_atomic.product_quantity), (0)::numeric) AS sold_units_30d,\n            count(DISTINCT fact_orders_atomic.metric_date) AS active_days_30d\n           FROM semantic.fact_orders_atomic\n          WHERE ((fact_orders_atomic.metric_date >= (CURRENT_DATE - '30 days'::interval)) AND (fact_orders_atomic.metric_date <= CURRENT_DATE))\n          GROUP BY fact_orders_atomic.platform_code, fact_orders_atomic.platform_sku, fact_orders_atomic.product_sku\n        ), joined_backlog AS (\n         SELECT i.snapshot_date,\n            i.platform_code,\n            i.shop_id,\n            i.product_id,\n            i.product_name,\n            i.platform_sku,\n            i.product_sku,\n            i.warehouse_name,\n            i.available_stock,\n            i.on_hand_stock,\n            i.inventory_value,\n            COALESCE(s.sold_units_30d, (0)::numeric) AS sold_units_30d,\n            COALESCE(s.active_days_30d, (0)::bigint) AS active_days_30d,\n            COALESCE(c.stock_delta, (0)::numeric) AS stock_delta,\n            COALESCE(c.inventory_value_delta, (0)::numeric) AS inventory_value_delta,\n            COALESCE(c.is_stagnant, false) AS is_stagnant,\n            COALESCE(c.snapshot_gap_days, 0) AS snapshot_gap_days,\n            COALESCE(c.estimated_stagnant_days, 0) AS estimated_stagnant_days,\n            COALESCE(c.stagnant_snapshot_count, 0) AS stagnant_snapshot_count\n           FROM ((latest_snapshot i\n             LEFT JOIN sales_30d s ON ((((i.platform_code)::text = (s.platform_code)::text) AND (COALESCE(i.platform_sku, ''::text) = COALESCE(s.platform_sku, ''::text)) AND (COALESCE(i.product_sku, ''::text) = COALESCE(s.product_sku, ''::text)))))\n             LEFT JOIN snapshot_change c ON ((((i.platform_code)::text = (c.platform_code)::text) AND (COALESCE(i.platform_sku, ''::text) = COALESCE(c.platform_sku, ''::text)) AND (COALESCE(i.product_sku, ''::text) = COALESCE(c.product_sku, ''::text)) AND (COALESCE(i.warehouse_name, ''::text) = COALESCE(c.warehouse_name, ''::text)))))\n        ), turnover_enriched AS (\n         SELECT base_1.snapshot_date,\n            base_1.platform_code,\n            base_1.shop_id,\n            base_1.product_id,\n            base_1.product_name,\n            base_1.platform_sku,\n            base_1.product_sku,\n            base_1.warehouse_name,\n            base_1.available_stock,\n            base_1.on_hand_stock,\n            base_1.inventory_value,\n            COALESCE(round((base_1.sold_units_30d / (NULLIF(base_1.active_days_30d, 0))::numeric), 2), (0)::numeric) AS daily_avg_sales,\n                CASE\n                    WHEN ((base_1.sold_units_30d > (0)::numeric) AND (base_1.active_days_30d > 0)) THEN round((COALESCE(base_1.available_stock, (0)::numeric) / NULLIF((base_1.sold_units_30d / (base_1.active_days_30d)::numeric), (0)::numeric)), 0)\n                    WHEN (COALESCE(base_1.available_stock, (0)::numeric) > (0)::numeric) THEN (9999)::numeric\n                    ELSE (0)::numeric\n                END AS estimated_turnover_days,\n            base_1.stock_delta,\n            base_1.inventory_value_delta,\n            base_1.is_stagnant,\n            base_1.snapshot_gap_days,\n            base_1.estimated_stagnant_days,\n            base_1.stagnant_snapshot_count\n           FROM joined_backlog base_1\n        )\n SELECT base.snapshot_date,\n    base.platform_code,\n    base.shop_id,\n    base.product_id,\n    base.product_name,\n    base.platform_sku,\n    base.product_sku,\n    base.warehouse_name,\n    base.available_stock,\n    base.on_hand_stock,\n    base.inventory_value,\n    base.daily_avg_sales,\n    base.estimated_turnover_days,\n    base.stock_delta,\n    base.inventory_value_delta,\n    base.is_stagnant,\n    base.snapshot_gap_days,\n    base.estimated_stagnant_days,\n    base.stagnant_snapshot_count,\n        CASE\n            WHEN ((base.estimated_turnover_days >= (60)::numeric) OR (base.stagnant_snapshot_count >= 3)) THEN 'high'::text\n            WHEN ((base.estimated_turnover_days >= (30)::numeric) OR (base.stagnant_snapshot_count >= 2)) THEN 'medium'::text\n            ELSE 'low'::text\n        END AS risk_level,\n    (((COALESCE(base.inventory_value, (0)::numeric) * 0.5) + ((base.estimated_stagnant_days * 10))::numeric) + (base.estimated_turnover_days * (2)::numeric)) AS clearance_priority_score\n   FROM turnover_enriched base\n  WITH NO DATA",
    "CREATE VIEW mart.inventory_current AS\n WITH ranked_inventory AS (\n         SELECT fact_inventory_snapshot.metric_date AS snapshot_date,\n            fact_inventory_snapshot.platform_code,\n            fact_inventory_snapshot.shop_id,\n            fact_inventory_snapshot.product_id,\n            fact_inventory_snapshot.product_name,\n            fact_inventory_snapshot.platform_sku,\n            fact_inventory_snapshot.sku_id,\n            fact_inventory_snapshot.product_sku,\n            fact_inventory_snapshot.warehouse_name,\n            fact_inventory_snapshot.warehouse_code,\n            fact_inventory_snapshot.available_stock,\n            fact_inventory_snapshot.on_hand_stock,\n            fact_inventory_snapshot.reserved_stock,\n            fact_inventory_snapshot.in_transit_stock,\n            fact_inventory_snapshot.stockout_qty,\n            fact_inventory_snapshot.reorder_point,\n            fact_inventory_snapshot.safety_stock,\n            fact_inventory_snapshot.unit_cost,\n            fact_inventory_snapshot.inventory_value,\n            fact_inventory_snapshot.currency_code,\n            row_number() OVER (PARTITION BY fact_inventory_snapshot.platform_code, COALESCE(fact_inventory_snapshot.shop_id, ''::text), COALESCE(fact_inventory_snapshot.platform_sku, ''::text), COALESCE(fact_inventory_snapshot.product_sku, ''::text) ORDER BY fact_inventory_snapshot.metric_date DESC, fact_inventory_snapshot.ingest_timestamp DESC) AS rn\n           FROM semantic.fact_inventory_snapshot\n        )\n SELECT ranked_inventory.snapshot_date,\n    ranked_inventory.platform_code,\n    ranked_inventory.shop_id,\n    ranked_inventory.product_id,\n    ranked_inventory.product_name,\n    ranked_inventory.platform_sku,\n    ranked_inventory.sku_id,\n    ranked_inventory.product_sku,\n    ranked_inventory.warehouse_name,\n    ranked_inventory.warehouse_code,\n    ranked_inventory.available_stock,\n    ranked_inventory.on_hand_stock,\n    ranked_inventory.reserved_stock,\n    ranked_inventory.in_transit_stock,\n    ranked_inventory.stockout_qty,\n    ranked_inventory.reorder_point,\n    ranked_inventory.safety_stock,\n    ranked_inventory.unit_cost,\n    ranked_inventory.inventory_value,\n    ranked_inventory.currency_code\n   FROM ranked_inventory\n  WHERE (ranked_inventory.rn = 1)",
    "CREATE VIEW mart.inventory_snapshot_company_daily AS\n WITH normalized AS (\n         SELECT inventory_snapshot_history.snapshot_date,\n            inventory_snapshot_history.platform_code,\n            COALESCE(NULLIF(btrim(inventory_snapshot_history.platform_sku), ''::text), NULLIF(btrim(inventory_snapshot_history.product_sku), ''::text), NULLIF(btrim(inventory_snapshot_history.sku_id), ''::text), NULLIF(btrim(inventory_snapshot_history.product_id), ''::text)) AS sku_key,\n            NULLIF(btrim(inventory_snapshot_history.platform_sku), ''::text) AS platform_sku,\n            NULLIF(btrim(inventory_snapshot_history.product_sku), ''::text) AS product_sku,\n            NULLIF(btrim(inventory_snapshot_history.sku_id), ''::text) AS sku_id,\n            NULLIF(btrim(inventory_snapshot_history.product_id), ''::text) AS product_id,\n            NULLIF(btrim(inventory_snapshot_history.product_name), ''::text) AS product_name,\n            NULLIF(btrim(inventory_snapshot_history.warehouse_name), ''::text) AS warehouse_name,\n            COALESCE(inventory_snapshot_history.available_stock, (0)::numeric) AS available_stock,\n            COALESCE(inventory_snapshot_history.on_hand_stock, (0)::numeric) AS on_hand_stock,\n            COALESCE(inventory_snapshot_history.inventory_value, (0)::numeric) AS inventory_value,\n            inventory_snapshot_history.ingest_timestamp\n           FROM mart.inventory_snapshot_history\n        ), deduplicated AS (\n         SELECT normalized.snapshot_date,\n            normalized.platform_code,\n            normalized.sku_key,\n            normalized.platform_sku,\n            normalized.product_sku,\n            normalized.sku_id,\n            normalized.product_id,\n            normalized.product_name,\n            normalized.warehouse_name,\n            normalized.available_stock,\n            normalized.on_hand_stock,\n            normalized.inventory_value,\n            normalized.ingest_timestamp,\n            row_number() OVER (PARTITION BY normalized.snapshot_date, normalized.platform_code, normalized.sku_key, COALESCE(normalized.warehouse_name, ''::text) ORDER BY normalized.ingest_timestamp DESC) AS rn\n           FROM normalized\n          WHERE (normalized.sku_key IS NOT NULL)\n        ), daily_latest AS (\n         SELECT deduplicated.snapshot_date,\n            deduplicated.platform_code,\n            deduplicated.sku_key,\n            deduplicated.platform_sku,\n            deduplicated.product_sku,\n            deduplicated.sku_id,\n            deduplicated.product_id,\n            deduplicated.product_name,\n            deduplicated.warehouse_name,\n            deduplicated.available_stock,\n            deduplicated.on_hand_stock,\n            deduplicated.inventory_value,\n            deduplicated.ingest_timestamp\n           FROM deduplicated\n          WHERE (deduplicated.rn = 1)\n        )\n SELECT daily_latest.snapshot_date,\n    daily_latest.platform_code,\n    daily_latest.sku_key,\n    max(daily_latest.platform_sku) AS platform_sku,\n    max(daily_latest.product_sku) AS product_sku,\n    max(daily_latest.sku_id) AS sku_id,\n    max(daily_latest.product_id) AS product_id,\n    max(daily_latest.product_name) AS product_name,\n    sum(daily_latest.available_stock) AS available_qty,\n    sum(daily_latest.on_hand_stock) AS on_hand_qty,\n    sum(daily_latest.inventory_value) AS inventory_value,\n    count(DISTINCT daily_latest.warehouse_name) FILTER (WHERE (daily_latest.warehouse_name IS NOT NULL)) AS warehouse_count,\n    max(daily_latest.ingest_timestamp) AS last_ingest_timestamp\n   FROM daily_latest\n  GROUP BY daily_latest.snapshot_date, daily_latest.platform_code, daily_latest.sku_key",
    "CREATE VIEW semantic.fact_products_atomic AS\n WITH raw_products AS (\n         SELECT fact_shopee_products_daily.platform_code,\n            fact_shopee_products_daily.shop_id,\n            fact_shopee_products_daily.data_domain,\n            fact_shopee_products_daily.granularity,\n            fact_shopee_products_daily.metric_date,\n            fact_shopee_products_daily.period_start_date,\n            fact_shopee_products_daily.period_end_date,\n            fact_shopee_products_daily.period_start_time,\n            fact_shopee_products_daily.period_end_time,\n            fact_shopee_products_daily.raw_data,\n            fact_shopee_products_daily.header_columns,\n            fact_shopee_products_daily.data_hash,\n            fact_shopee_products_daily.ingest_timestamp,\n            fact_shopee_products_daily.currency_code\n           FROM b_class.fact_shopee_products_daily\n        UNION ALL\n         SELECT fact_shopee_products_weekly.platform_code,\n            fact_shopee_products_weekly.shop_id,\n            fact_shopee_products_weekly.data_domain,\n            fact_shopee_products_weekly.granularity,\n            fact_shopee_products_weekly.metric_date,\n            fact_shopee_products_weekly.period_start_date,\n            fact_shopee_products_weekly.period_end_date,\n            fact_shopee_products_weekly.period_start_time,\n            fact_shopee_products_weekly.period_end_time,\n            fact_shopee_products_weekly.raw_data,\n            fact_shopee_products_weekly.header_columns,\n            fact_shopee_products_weekly.data_hash,\n            fact_shopee_products_weekly.ingest_timestamp,\n            fact_shopee_products_weekly.currency_code\n           FROM b_class.fact_shopee_products_weekly\n        UNION ALL\n         SELECT fact_shopee_products_monthly.platform_code,\n            fact_shopee_products_monthly.shop_id,\n            fact_shopee_products_monthly.data_domain,\n            fact_shopee_products_monthly.granularity,\n            fact_shopee_products_monthly.metric_date,\n            fact_shopee_products_monthly.period_start_date,\n            fact_shopee_products_monthly.period_end_date,\n            fact_shopee_products_monthly.period_start_time,\n            fact_shopee_products_monthly.period_end_time,\n            fact_shopee_products_monthly.raw_data,\n            fact_shopee_products_monthly.header_columns,\n            fact_shopee_products_monthly.data_hash,\n            fact_shopee_products_monthly.ingest_timestamp,\n            fact_shopee_products_monthly.currency_code\n           FROM b_class.fact_shopee_products_monthly\n        UNION ALL\n         SELECT fact_tiktok_products_daily.platform_code,\n            fact_tiktok_products_daily.shop_id,\n            fact_tiktok_products_daily.data_domain,\n            fact_tiktok_products_daily.granularity,\n            fact_tiktok_products_daily.metric_date,\n            fact_tiktok_products_daily.period_start_date,\n            fact_tiktok_products_daily.period_end_date,\n            fact_tiktok_products_daily.period_start_time,\n            fact_tiktok_products_daily.period_end_time,\n            fact_tiktok_products_daily.raw_data,\n            fact_tiktok_products_daily.header_columns,\n            fact_tiktok_products_daily.data_hash,\n            fact_tiktok_products_daily.ingest_timestamp,\n            fact_tiktok_products_daily.currency_code\n           FROM b_class.fact_tiktok_products_daily\n        UNION ALL\n         SELECT fact_tiktok_products_weekly.platform_code,\n            fact_tiktok_products_weekly.shop_id,\n            fact_tiktok_products_weekly.data_domain,\n            fact_tiktok_products_weekly.granularity,\n            fact_tiktok_products_weekly.metric_date,\n            fact_tiktok_products_weekly.period_start_date,\n            fact_tiktok_products_weekly.period_end_date,\n            fact_tiktok_products_weekly.period_start_time,\n            fact_tiktok_products_weekly.period_end_time,\n            fact_tiktok_products_weekly.raw_data,\n            fact_tiktok_products_weekly.header_columns,\n            fact_tiktok_products_weekly.data_hash,\n            fact_tiktok_products_weekly.ingest_timestamp,\n            fact_tiktok_products_weekly.currency_code\n           FROM b_class.fact_tiktok_products_weekly\n        UNION ALL\n         SELECT fact_tiktok_products_monthly.platform_code,\n            fact_tiktok_products_monthly.shop_id,\n            fact_tiktok_products_monthly.data_domain,\n            fact_tiktok_products_monthly.granularity,\n            fact_tiktok_products_monthly.metric_date,\n            fact_tiktok_products_monthly.period_start_date,\n            fact_tiktok_products_monthly.period_end_date,\n            fact_tiktok_products_monthly.period_start_time,\n            fact_tiktok_products_monthly.period_end_time,\n            fact_tiktok_products_monthly.raw_data,\n            fact_tiktok_products_monthly.header_columns,\n            fact_tiktok_products_monthly.data_hash,\n            fact_tiktok_products_monthly.ingest_timestamp,\n            fact_tiktok_products_monthly.currency_code\n           FROM b_class.fact_tiktok_products_monthly\n        UNION ALL\n         SELECT fact_miaoshou_products_daily.platform_code,\n            fact_miaoshou_products_daily.shop_id,\n            fact_miaoshou_products_daily.data_domain,\n            fact_miaoshou_products_daily.granularity,\n            fact_miaoshou_products_daily.metric_date,\n            fact_miaoshou_products_daily.period_start_date,\n            fact_miaoshou_products_daily.period_end_date,\n            fact_miaoshou_products_daily.period_start_time,\n            fact_miaoshou_products_daily.period_end_time,\n            fact_miaoshou_products_daily.raw_data,\n            fact_miaoshou_products_daily.header_columns,\n            fact_miaoshou_products_daily.data_hash,\n            fact_miaoshou_products_daily.ingest_timestamp,\n            fact_miaoshou_products_daily.currency_code\n           FROM b_class.fact_miaoshou_products_daily\n        UNION ALL\n         SELECT fact_miaoshou_products_weekly.platform_code,\n            fact_miaoshou_products_weekly.shop_id,\n            fact_miaoshou_products_weekly.data_domain,\n            fact_miaoshou_products_weekly.granularity,\n            fact_miaoshou_products_weekly.metric_date,\n            fact_miaoshou_products_weekly.period_start_date,\n            fact_miaoshou_products_weekly.period_end_date,\n            fact_miaoshou_products_weekly.period_start_time,\n            fact_miaoshou_products_weekly.period_end_time,\n            fact_miaoshou_products_weekly.raw_data,\n            fact_miaoshou_products_weekly.header_columns,\n            fact_miaoshou_products_weekly.data_hash,\n            fact_miaoshou_products_weekly.ingest_timestamp,\n            fact_miaoshou_products_weekly.currency_code\n           FROM b_class.fact_miaoshou_products_weekly\n        UNION ALL\n         SELECT fact_miaoshou_products_monthly.platform_code,\n            fact_miaoshou_products_monthly.shop_id,\n            fact_miaoshou_products_monthly.data_domain,\n            fact_miaoshou_products_monthly.granularity,\n            fact_miaoshou_products_monthly.metric_date,\n            fact_miaoshou_products_monthly.period_start_date,\n            fact_miaoshou_products_monthly.period_end_date,\n            fact_miaoshou_products_monthly.period_start_time,\n            fact_miaoshou_products_monthly.period_end_time,\n            fact_miaoshou_products_monthly.raw_data,\n            fact_miaoshou_products_monthly.header_columns,\n            fact_miaoshou_products_monthly.data_hash,\n            fact_miaoshou_products_monthly.ingest_timestamp,\n            fact_miaoshou_products_monthly.currency_code\n           FROM b_class.fact_miaoshou_products_monthly\n        ), mapped AS (\n         SELECT raw_products.platform_code,\n            COALESCE(NULLIF(TRIM(BOTH FROM COALESCE(raw_products.shop_id, ''::character varying)), ''::text), 'unknown'::text) AS shop_id,\n            raw_products.data_domain,\n            raw_products.granularity,\n            raw_products.metric_date,\n            raw_products.period_start_date,\n            raw_products.period_end_date,\n            raw_products.period_start_time,\n            raw_products.period_end_time,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'product_id'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS product_id,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'product_name'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS product_name,\n            COALESCE((raw_products.raw_data ->> '平台SKU'::text), (raw_products.raw_data ->> 'platform_sku'::text), (raw_products.raw_data ->> 'Platform SKU'::text), (raw_products.raw_data ->> 'SKU'::text), (raw_products.raw_data ->> 'sku'::text)) AS platform_sku,\n            COALESCE((raw_products.raw_data ->> '类目'::text), (raw_products.raw_data ->> '分类'::text), (raw_products.raw_data ->> 'category'::text), (raw_products.raw_data ->> 'Category'::text)) AS category,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'item_status'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS item_status,\n            COALESCE((raw_products.raw_data ->> '价格'::text), (raw_products.raw_data ->> '单价'::text), (raw_products.raw_data ->> '售价'::text), (raw_products.raw_data ->> 'price'::text), (raw_products.raw_data ->> 'Price'::text)) AS price_raw,\n            COALESCE((raw_products.raw_data ->> '库存'::text), (raw_products.raw_data ->> '库存数量'::text), (raw_products.raw_data ->> 'stock'::text), (raw_products.raw_data ->> 'Stock'::text), (raw_products.raw_data ->> 'inventory'::text)) AS stock_raw,\n            COALESCE((raw_products.raw_data ->> '浏览量'::text), (raw_products.raw_data ->> '页面浏览次数'::text), (raw_products.raw_data ->> 'page_views'::text), (raw_products.raw_data ->> 'Page Views'::text), (raw_products.raw_data ->> 'views'::text), (raw_products.raw_data ->> 'pv'::text)) AS page_views_raw,\n            COALESCE((raw_products.raw_data ->> '访客数'::text), (raw_products.raw_data ->> '独立访客'::text), (raw_products.raw_data ->> 'unique_visitors'::text), (raw_products.raw_data ->> 'Unique Visitors'::text), (raw_products.raw_data ->> 'uv'::text)) AS unique_visitors_raw,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'impressions'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS impressions_raw,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'clicks'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS clicks_raw,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'conversion_rate'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS conversion_rate_raw,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'order_count'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS order_count_raw,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'sales_amount'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS sales_amount_raw,\n            semantic.resolve_alias(raw_products.raw_data, (raw_products.data_domain)::text, 'sales_volume'::text, (raw_products.platform_code)::text, (raw_products.granularity)::text) AS sales_volume_raw,\n            COALESCE((raw_products.raw_data ->> '评价数'::text), (raw_products.raw_data ->> '评论数'::text), (raw_products.raw_data ->> 'review_count'::text), (raw_products.raw_data ->> 'Review Count'::text), (raw_products.raw_data ->> 'reviews'::text)) AS review_count_raw,\n            raw_products.raw_data,\n            raw_products.header_columns,\n            raw_products.data_hash,\n            raw_products.ingest_timestamp,\n            raw_products.currency_code\n           FROM raw_products\n        ), cleaned AS (\n         SELECT mapped.platform_code,\n            mapped.shop_id,\n            mapped.data_domain,\n            mapped.granularity,\n            mapped.metric_date,\n            mapped.period_start_date,\n            mapped.period_end_date,\n            mapped.period_start_time,\n            mapped.period_end_time,\n            mapped.product_id,\n            mapped.product_name,\n            mapped.platform_sku,\n            mapped.category,\n            mapped.item_status,\n                CASE\n                    WHEN (mapped.price_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.price_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS price,\n                CASE\n                    WHEN (mapped.stock_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.stock_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS stock,\n                CASE\n                    WHEN (mapped.page_views_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.page_views_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS page_views,\n                CASE\n                    WHEN (mapped.unique_visitors_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.unique_visitors_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS unique_visitors,\n                CASE\n                    WHEN (mapped.impressions_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.impressions_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS impressions,\n                CASE\n                    WHEN (mapped.clicks_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.clicks_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS clicks,\n                CASE\n                    WHEN (mapped.conversion_rate_raw IS NULL) THEN NULL::numeric\n                    ELSE ((NULLIF(regexp_replace(replace(replace(replace(replace(replace(mapped.conversion_rate_raw, '%'::text, ''::text), ','::text, '.'::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric / 100.0)\n                END AS conversion_rate,\n                CASE\n                    WHEN (mapped.order_count_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.order_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS order_count,\n                CASE\n                    WHEN (mapped.sales_amount_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.sales_amount_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS sales_amount,\n                CASE\n                    WHEN (mapped.sales_volume_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.sales_volume_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS sales_volume,\n                CASE\n                    WHEN (mapped.review_count_raw IS NULL) THEN NULL::numeric\n                    ELSE (NULLIF(regexp_replace(replace(replace(replace(replace(mapped.review_count_raw, ','::text, ''::text), ' '::text, ''::text), chr(8212), ''::text), chr(8211), ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric\n                END AS review_count,\n            mapped.raw_data,\n            mapped.header_columns,\n            mapped.data_hash,\n            mapped.ingest_timestamp,\n            mapped.currency_code\n           FROM mapped\n        ), deduplicated AS (\n         SELECT cleaned.platform_code,\n            cleaned.shop_id,\n            cleaned.data_domain,\n            cleaned.granularity,\n            cleaned.metric_date,\n            cleaned.period_start_date,\n            cleaned.period_end_date,\n            cleaned.period_start_time,\n            cleaned.period_end_time,\n            cleaned.product_id,\n            cleaned.product_name,\n            cleaned.platform_sku,\n            cleaned.category,\n            cleaned.item_status,\n            cleaned.price,\n            cleaned.stock,\n            cleaned.page_views,\n            cleaned.unique_visitors,\n            cleaned.impressions,\n            cleaned.clicks,\n            cleaned.conversion_rate,\n            cleaned.order_count,\n            cleaned.sales_amount,\n            cleaned.sales_volume,\n            cleaned.review_count,\n            cleaned.raw_data,\n            cleaned.header_columns,\n            cleaned.data_hash,\n            cleaned.ingest_timestamp,\n            cleaned.currency_code,\n            row_number() OVER (PARTITION BY cleaned.platform_code, cleaned.shop_id, cleaned.data_hash ORDER BY\n                CASE cleaned.granularity\n                    WHEN 'daily'::text THEN 1\n                    WHEN 'weekly'::text THEN 2\n                    WHEN 'monthly'::text THEN 3\n                    ELSE 9\n                END, cleaned.ingest_timestamp DESC) AS rn\n           FROM cleaned\n        )\n SELECT deduplicated.platform_code,\n    deduplicated.shop_id,\n    deduplicated.data_domain,\n    deduplicated.granularity,\n    deduplicated.metric_date,\n    deduplicated.period_start_date,\n    deduplicated.period_end_date,\n    deduplicated.period_start_time,\n    deduplicated.period_end_time,\n    deduplicated.product_id,\n    deduplicated.product_name,\n    deduplicated.platform_sku,\n    deduplicated.category,\n    deduplicated.item_status,\n    COALESCE(deduplicated.price, (0)::numeric) AS price,\n    COALESCE(deduplicated.stock, (0)::numeric) AS stock,\n    COALESCE(deduplicated.page_views, (0)::numeric) AS page_views,\n    COALESCE(deduplicated.unique_visitors, (0)::numeric) AS unique_visitors,\n    COALESCE(deduplicated.impressions, (0)::numeric) AS impressions,\n    COALESCE(deduplicated.clicks, (0)::numeric) AS clicks,\n    COALESCE(deduplicated.conversion_rate, (0)::numeric) AS conversion_rate,\n    COALESCE(deduplicated.order_count, (0)::numeric) AS order_count,\n    COALESCE(deduplicated.sales_amount, (0)::numeric) AS sales_amount,\n    COALESCE(deduplicated.sales_volume, (0)::numeric) AS sales_volume,\n    COALESCE(deduplicated.review_count, (0)::numeric) AS review_count,\n    deduplicated.raw_data,\n    deduplicated.header_columns,\n    deduplicated.data_hash,\n    deduplicated.ingest_timestamp,\n    deduplicated.currency_code\n   FROM deduplicated\n  WHERE (deduplicated.rn = 1)",
    "CREATE VIEW mart.product_day_kpi AS\n SELECT fact_products_atomic.metric_date AS period_date,\n    fact_products_atomic.platform_code,\n    fact_products_atomic.shop_id,\n    fact_products_atomic.platform_sku,\n    fact_products_atomic.product_id,\n    fact_products_atomic.product_name,\n    COALESCE(sum(fact_products_atomic.sales_amount), (0)::numeric) AS sales_amount,\n    COALESCE(sum(fact_products_atomic.order_count), (0)::numeric) AS order_count,\n    COALESCE(sum(fact_products_atomic.sales_volume), (0)::numeric) AS sales_volume,\n    COALESCE(sum(fact_products_atomic.page_views), (0)::numeric) AS page_views,\n    COALESCE(sum(fact_products_atomic.unique_visitors), (0)::numeric) AS unique_visitors,\n    COALESCE(sum(fact_products_atomic.impressions), (0)::numeric) AS impressions,\n    COALESCE(sum(fact_products_atomic.clicks), (0)::numeric) AS clicks,\n        CASE\n            WHEN (COALESCE(sum(fact_products_atomic.unique_visitors), (0)::numeric) > (0)::numeric) THEN round(((COALESCE(sum(fact_products_atomic.order_count), (0)::numeric) * 100.0) / sum(fact_products_atomic.unique_visitors)), 2)\n            ELSE (0)::numeric\n        END AS conversion_rate\n   FROM semantic.fact_products_atomic\n  WHERE ((fact_products_atomic.granularity)::text = 'daily'::text)\n  GROUP BY fact_products_atomic.metric_date, fact_products_atomic.platform_code, fact_products_atomic.shop_id, fact_products_atomic.platform_sku, fact_products_atomic.product_id, fact_products_atomic.product_name",
    "CREATE TABLE ops.cloud_sync_receive_log (\n    id integer NOT NULL,\n    receive_id character varying(100) NOT NULL,\n    source_environment character varying(64),\n    checkpoint_scope character varying(64) DEFAULT 'b_class'::character varying NOT NULL,\n    source_table_name character varying(255) NOT NULL,\n    source_file_id integer,\n    platform_code character varying(32),\n    data_domain character varying(64),\n    granularity character varying(32),\n    business_date_min date,\n    business_date_max date,\n    source_latest_ingest_timestamp timestamp with time zone,\n    written_rows integer DEFAULT 0 NOT NULL,\n    status character varying(32) DEFAULT 'completed'::character varying NOT NULL,\n    created_at timestamp with time zone DEFAULT now() NOT NULL,\n    error_message text\n)",
    "CREATE SEQUENCE ops.cloud_sync_receive_log_id_seq\n    AS integer\n    START WITH 1\n    INCREMENT BY 1\n    NO MINVALUE\n    NO MAXVALUE\n    CACHE 1",
    "ALTER SEQUENCE ops.cloud_sync_receive_log_id_seq OWNED BY ops.cloud_sync_receive_log.id",
