    "CREATE MATERIALIZED VIEW public.mv_inventory_age_day AS\n SELECT CURRENT_DATE AS snapshot_date,\n    'stub'::character varying AS shop_code,\n    'stub'::character varying AS normalized_sku,\n    0.0::numeric(18,3) AS on_hand_qty,\n    0.0::numeric(18,4) AS avg_cost,\n    CURRENT_DATE AS earliest_receipt_date,\n    0 AS age_days,\n    CURRENT_TIMESTAMP AS refreshed_at\n  WHERE (1 = 0)\n  WITH NO DATA",
    "CREATE MATERIALIZED VIEW public.mv_inventory_turnover_daily AS\n SELECT CURRENT_DATE AS snapshot_date,\n    'placeholder'::text AS platform_code,\n    'placeholder'::text AS shop_id,\n    0.0 AS turnover_rate,\n    0 AS days_on_hand\n  WHERE false\n  WITH NO DATA",
    "CREATE MATERIALIZED VIEW public.mv_pnl_shop_month AS\n SELECT 'stub'::text AS period_month,\n    'stub'::text AS shop_code,\n    0.0::numeric(18,2) AS revenue,\n    0.0::numeric(18,2) AS cogs,\n    0.0::numeric(18,2) AS expenses,\n    0.0::numeric(18,2) AS contribution_profit\n  WHERE (1 = 0)\n  WITH NO DATA",
    "CREATE MATERIALIZED VIEW public.mv_product_topn_day AS\n SELECT CURRENT_DATE AS order_date,\n    'stub'::character varying AS platform_code,\n    'stub'::character varying AS shop_id,\n    'stub'::character varying AS platform_sku,\n    'stub'::character varying AS product_name,\n    0 AS total_qty,\n    0.0::numeric(18,2) AS total_revenue,\n    0 AS order_count,\n    CURRENT_TIMESTAMP AS refreshed_at\n  WHERE (1 = 0)\n  WITH NO DATA",
    "CREATE TABLE public.mv_refresh_log (\n    id integer NOT NULL,\n    view_name character varying(128) NOT NULL,\n    refresh_started_at timestamp with time zone DEFAULT now() NOT NULL,\n    refresh_completed_at timestamp with time zone,\n    duration_seconds double precision,\n    row_count integer,\n    status character varying(20) DEFAULT 'running'::character varying,\n    error_message text,\n    triggered_by character varying(64) DEFAULT 'scheduler'::character varying,\n    CONSTRAINT chk_status CHECK (((status)::text = ANY (ARRAY[('running'::character varying)::text, ('success'::character varying)::text, ('failed'::character varying)::text])))\n)",
    "CREATE SEQUENCE public.mv_refresh_log_id_seq\n    AS integer\n    START WITH 1\n    INCREMENT BY 1\n    NO MINVALUE\n    NO MAXVALUE\n    CACHE 1",
    "ALTER SEQUENCE public.mv_refresh_log_id_seq OWNED BY public.mv_refresh_log.id",
    "CREATE MATERIALIZED VIEW public.mv_shop_health_summary AS\n SELECT shs.platform_code,\n    shs.shop_id,\n    ds.shop_name,\n    shs.metric_date,\n    shs.granularity,\n    shs.health_score,\n    shs.gmv_score,\n    shs.conversion_score,\n    shs.inventory_score,\n    shs.service_score,\n    shs.gmv,\n    shs.conversion_rate,\n    shs.inventory_turnover,\n    shs.customer_satisfaction,\n    shs.risk_level,\n    shs.risk_factors,\n    row_number() OVER (PARTITION BY shs.metric_date, shs.granularity ORDER BY shs.health_score DESC) AS health_rank,\n    shs.created_at,\n    shs.updated_at\n   FROM (c_class.shop_health_scores shs\n     LEFT JOIN core.dim_shops ds ON ((((shs.platform_code)::text = (ds.platform_code)::text) AND ((shs.shop_id)::text = (ds.shop_id)::text))))\n  WHERE (shs.metric_date >= (CURRENT_DATE - '90 days'::interval))\n  WITH NO DATA",
    "CREATE MATERIALIZED VIEW public.mv_shop_pnl_daily AS\n SELECT CURRENT_DATE AS sale_date,\n    'placeholder'::text AS platform_code,\n    'placeholder'::text AS shop_id,\n    0.0 AS revenue,\n    0.0 AS cost,\n    0.0 AS profit\n  WHERE false\n  WITH NO DATA",
    "CREATE MATERIALIZED VIEW public.mv_shop_traffic_day AS\n SELECT CURRENT_DATE AS metric_date,\n    'stub'::character varying AS platform_code,\n    'stub'::character varying AS shop_id,\n    0 AS pageviews,\n    0 AS visitors,\n    0 AS orders,\n    CURRENT_TIMESTAMP AS refreshed_at\n  WHERE (1 = 0)\n  WITH NO DATA",
    "CREATE MATERIALIZED VIEW public.mv_traffic_daily AS\n SELECT CURRENT_DATE AS metric_date,\n    'placeholder'::text AS platform_code,\n    'placeholder'::text AS shop_id,\n    0 AS views,\n    0 AS clicks,\n    0 AS visitors\n  WHERE false\n  WITH NO DATA",
    "CREATE MATERIALIZED VIEW public.mv_vendor_performance AS\n SELECT 'stub'::character varying AS vendor_code,\n    'stub'::character varying AS vendor_name,\n    0 AS total_pos,\n    0.0::numeric(18,2) AS total_po_value,\n    0.0::numeric(10,2) AS avg_lead_time_days,\n    0.0::numeric(5,2) AS variance_rate_pct,\n    CURRENT_TIMESTAMP AS refreshed_at\n  WHERE (1 = 0)\n  WITH NO DATA",
